fields.InputDefinition:
{
  "goal": "Open the Lists app using the application switcher dropdown next to the logo (NOT the Ctrl+K search box). In the Lists section, use the Create list action to create a new list named 'Regression Test List 2' for the Members entity — when choosing the entity for the list, select the one named exactly 'Members' (NOT 'Memberships', 'Membership Types', or any other Member-prefixed entity). Then add at least one Member record to the list. Confirm success by reaching a state where the new list 'Regression Test List 2' exists and displays the added Member record. Pages can take 10-30s to load in this resource-constrained env - wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
